WITH unpacked AS (SELECT id, coupon_codes, ship_to.zip AS ship_zip, attributes['device'] AS device, SIZE(attributes) AS num_attributes, ARRAY_MAX(TRANSFORM(items, x -> x.price)) AS max_item_price, COALESCE(ship_to.country, 'UNKNOWN') AS country_or_unknown FROM carts WHERE ARRAY_CONTAINS(coupon_codes, 'WELCOME5')) SELECT id, ship_zip, COUNT(max_item_price) OVER (ORDER BY max_item_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_max_item_price, AVG(max_item_price) OVER (ORDER BY max_item_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_max_item_price, SUM(max_item_price) OVER (ORDER BY max_item_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_max_item_price, NTILE(3) OVER (ORDER BY max_item_price, id) AS max_item_price_bucket FROM unpacked
